  "[codex-bridge] Erro inesperado: {0}": "[codex-bridge] Lỗi bất ngờ: {0}",
  "Aguardando resposta no Habblaud…": "Đang chờ câu trả lời trong Habblaud…",
  "Uso: npm run codex:<install|uninstall|status> [-- opções]\n\n  install     acrescenta os hooks do Habblaud no hooks.json de cada pasta do Codex (faz backup antes)\n  uninstall   tira os hooks do Habblaud de cada pasta (os outros hooks ficam)\n  status      mostra se os hooks estão lá e se o Habblaud está respondendo\n\nOpções:\n  --dry-run        mostra o que mudaria, sem gravar nada\n  --conta <id>     só a pasta desta conta (o nome da pasta, ex.: .codex)\n  --port <n>       porta do Habblaud (padrão: HABBLAUD_PORT ou {0})\n  --espera <s>     quanto o Codex espera sua resposta no Habblaud antes de pedir a aprovação no terminal\n                   (padrão: {1} s; entre {2} e {3})\n  --node <caminho> o Node {4}+ que roda os hooks (padrão: o `node` do shell de login, se for {5}+;\n                   senão o primeiro {6}+ entre /opt/homebrew/bin, /usr/local/bin e o deste comando)\n  -h, --help       mostra esta ajuda\n\nPastas: HABBLAUD_CODEX_DIRS (lista separada por vírgula) ou CODEX_HOME e as pastas ~/.codex* do Codex.\nDepois de instalar, abra o Codex e aprove os hooks do Habblaud em /hooks.": "Cách dùng: npm run codex:<install|uninstall|status> [-- tùy chọn]\n\n  install     thêm hook Habblaud vào hooks.json trong từng thư mục Codex (sao lưu trước)\n  uninstall   chỉ gỡ hook Habblaud, giữ hook khác\n  status      xem hook đã cài và Habblaud có phản hồi không\n\nTùy chọn:\n  --dry-run       xem thay đổi, không ghi tệp\n  --conta <id>    chỉ thư mục tài khoản này (ví dụ .codex)\n  --port <n>      cổng Habblaud (mặc định HABBLAUD_PORT hoặc {0})\n  --espera <s>    thời gian chờ trả lời ở Habblaud trước khi xin quyền trong terminal\n                  (mặc định {1} giây; từ {2} tới {3})\n  --node <path>   Node {4}+ chạy hook (mặc định node của login shell nếu là {5}+;\n                  nếu không, dùng bản {6}+ đầu tiên trong /opt/homebrew/bin, /usr/local/bin hoặc bản chạy lệnh này)\n  -h, --help      hiện trợ giúp\n\nThư mục: HABBLAUD_CODEX_DIRS (cách nhau bằng dấu phẩy) hoặc CODEX_HOME và ~/.codex*.\nSau khi cài, mở Codex và phê duyệt hook Habblaud trong /hooks.",
  "\"hooks\" em formato desconhecido; nada foi alterado": "\"hooks\" có định dạng không xác định; không thay đổi gì",
  "\"hooks.{0}\" em formato desconhecido; nada foi alterado": "\"hooks.{0}\" có định dạng không xác định; không thay đổi gì",
