  "atualizado em {0}": "đã cập nhật trong {0}",
  "não estava instalado": "chưa được cài",
  "hooks do Habblaud removidos": "Đã gỡ hook Habblaud",
  "--conta precisa do nome da pasta da conta (ex.: .codex).": "--conta cần tên thư mục tài khoản (ví dụ .codex).",
  "--espera precisa de um número de segundos entre {0} e {1}.": "--espera cần số giây từ {0} tới {1}.",
  "--node precisa do caminho absoluto de um Node 22+ (ex.: /opt/homebrew/bin/node).": "--node cần đường dẫn tuyệt đối tới Node 22+ (ví dụ /opt/homebrew/bin/node).",
  "diga o que fazer: install, uninstall ou status.\n\n{0}": "chỉ định thao tác: install, uninstall hoặc status.\n\n{0}",
