  "! nome antigo ainda registrado: {0}; npm run mod:install troca pelo habblaud": "! vẫn đăng ký tên cũ: {0}; npm run mod:install thay bằng habblaud",
  "! tap de statusline antigo ainda instalado junto com o mod: npm run mod:install tira (ou npm run usage:uninstall)": "! statusline cũ vẫn cài cùng mod: npm run mod:install sẽ gỡ (hoặc npm run usage:uninstall)",
  "tap de statusline antigo instalado (jeito antigo; o mod o substitui)": "đã cài statusline cũ (cách cũ; mod thay thế)",
  "! hook de permissão antigo ainda no settings.json junto com o plugin: os dois respondem; npm run mod:install tira (ou npm run hooks:uninstall)": "! hook quyền cũ còn trong settings.json cùng plugin: cả hai sẽ trả lời; npm run mod:install sẽ gỡ (hoặc npm run hooks:uninstall)",
