  "Nenhuma conta do Claude Code encontrada (~/.claude* com projects/ ou sessions/). Use --conta <pasta> ou HABBLAUD_CLAUDE_DIRS.": "Không thấy tài khoản Claude Code (~/.claude* có projects/ hoặc sessions/). Dùng --conta <folder> hoặc HABBLAUD_CLAUDE_DIRS.",
  "Não achei {0}: esta pasta não tem o mod (versão antiga do Habblaud? rode git pull).": "Không thấy {0}: thư mục này không có mod (bản Habblaud cũ? chạy git pull).",
  "Não consegui rodar o Claude Code: {0}.": "Không thể chạy Claude Code: {0}.",
  "Instale o Claude Code (https://code.claude.com) ou diga onde ele está: npm run mod:<comando> -- --claude <caminho>": "Cài Claude Code (https://code.claude.com) hoặc chỉ đường dẫn: npm run mod:<command> -- --claude <path>",
  "! Não entendi a versão do Claude Code (\"{0}\"); sigo assim mesmo.": "! Không đọc được phiên bản Claude Code (\"{0}\"); vẫn tiếp tục.",
  "O mod precisa do Claude Code {0} ou mais novo, e este é o {1}.": "Mod cần Claude Code {0} trở lên, bản này là {1}.",
  "Atualize o Claude Code (claude update) e rode de novo. Ou use o jeito antigo, que funciona em versões anteriores:": "Cập nhật Claude Code (claude update) rồi chạy lại. Hoặc dùng cách cũ hỗ trợ bản trước:",
  "  npm run usage:install    # uso de 5h/semanal ao vivo (tap de statusline)": "  npm run usage:install    # mức dùng 5 giờ/tuần trực tiếp (statusline)",
  "  npm run hooks:install    # responder pedidos de permissão pelo escritório": "  npm run hooks:install    # trả lời yêu cầu cấp quyền từ văn phòng",
  "Claude Code {0}{1} · Habblaud {2} em {3}": "Claude Code {0}{1} · Habblaud {2} trong {3}",
  "(versão desconhecida)": "(không rõ phiên bản)",
  " — o mod precisa do {0}+": " — mod cần {0}+",
  "✓ pasta do uso criada: {0}": "✓ đã tạo thư mục mức dùng: {0}",
  "! não consegui criar {0} ({1}); o uso ao vivo não vai ser gravado": "! không thể tạo {0} ({1}); không ghi được mức dùng trực tiếp",
  "    ✗ settings.json: {0}": "    ✗ settings.json: {0}",
