  "  ✗ {0}: falhou ({1})": "  ✗ {0}: thất bại ({1})",
  "  ! nome antigo ainda registrado: {0}; rode npm run mod:install de novo (ou confira com npm run mod:status)": "  ! tên cũ vẫn đăng ký: {0}; chạy lại npm run mod:install (hoặc kiểm tra npm run mod:status)",
  "  ✗ settings.json: {0}; o tap e o hook antigos não foram conferidos": "  ✗ settings.json: {0}; chưa kiểm tra statusline và hook cũ",
  "  ! disableAllHooks está ligado no settings.json desta conta: o mod não roda até você desligar": "  ! disableAllHooks đang bật trong settings.json: mod chưa chạy được tới khi tắt mục đó",
  "  ~ {0} (simulação: nada gravado)": "  ~ {0} (chạy thử: không ghi tệp)",
  "    backup do settings.json em {0}": "    sao lưu settings.json trong {0}",
  "  ✗ não consegui gravar o settings.json ({0}); o tap e o hook antigos continuam": "  ✗ không thể ghi settings.json ({0}); giữ statusline và hook cũ",
  "Pronto. Sessões novas do Claude Code já carregam o mod; nas que já estão abertas, rode /reload-plugins (ou": "Xong. Phiên Claude Code mới tự tải mod; với phiên đang mở, chạy /reload-plugins (hoặc",
  "reabra a sessão). O uso de 5h/semanal chega ao Habblaud depois da próxima resposta de cada sessão.": "mở lại phiên). Mức dùng 5 giờ/tuần tới Habblaud sau phản hồi tiếp theo của từng phiên.",
  "Para conferir: npm run mod:status · Para desfazer: npm run mod:uninstall": "Kiểm tra: npm run mod:status · Hoàn tác: npm run mod:uninstall",
  "Pronto. Sessões já abertas continuam com o mod até /reload-plugins (ou até reabrir a sessão).": "Xong. Phiên đang mở giữ mod tới khi /reload-plugins (hoặc mở lại phiên).",
  "Para voltar ao jeito antigo (Claude Code anterior ao 2.1.287): npm run usage:install e npm run hooks:install": "Để dùng cách cũ (Claude Code trước 2.1.287): npm run usage:install và npm run hooks:install",
  "Habblaud em http://127.0.0.1:{0}": "Habblaud tại http://127.0.0.1:{0}",
  "{0}: fora do ar (o mod segue gravando o uso; os pedidos de permissão ficam só no terminal).": "{0}: không chạy (mod vẫn ghi mức dùng; yêu cầu quyền chỉ ở terminal).",
  "{0}: no ar e respondendo pedidos de permissão (com alguma página aberta).": "{0}: đang chạy và xử lý yêu cầu quyền (khi có trang mở).",
  "{0}: no ar, mas responder pelo escritório está desligado (porta exposta na rede ou HABBLAUD_TERMINAL=0).": "{0}: đang chạy nhưng trả lời từ văn phòng đã tắt (cổng mở ra mạng hoặc HABBLAUD_TERMINAL=0).",
  "Mensagens pelo escritório: ligadas (chegam às sessões abertas com o plugin {0}).": "Tin nhắn từ văn phòng: bật (tới phiên mở có plugin {0}).",
  "Mensagens pelo escritório: desligadas no Habblaud (porta exposta na rede, HABBLAUD_TERMINAL=0 ou HABBLAUD_MENSAGENS=0).": "Tin nhắn từ văn phòng: tắt trong Habblaud (cổng mở ra mạng, HABBLAUD_TERMINAL=0 hoặc HABBLAUD_MENSAGENS=0).",
  "não consegui consultar o Claude Code ({0}); o mod não foi conferido.": "không thể truy vấn Claude Code ({0}); chưa kiểm tra mod.",
  "mod na {0}: {1}": "mod trên {0}: {1}",
  "Dica para a {0}: {1}": "Gợi ý cho {0}: {1}",
  "não consegui atualizar o mod na {0}: {1} ({2}). Tente: npm run mod:install": "không thể cập nhật mod trên {0}: {1} ({2}). Thử: npm run mod:install",
  "Mod atualizado para {0} na {1}; sessões abertas: /reload-plugins": "Đã cập nhật mod lên {0} trên {1}; phiên mở: /reload-plugins",
  "[mod] Erro: {0}": "[mod] Lỗi: {0}",
  "[mod] Erro inesperado: {0}": "[mod] Lỗi bất ngờ: {0}",
  "Uso: npm run usage:<install|uninstall|status> [-- opções]\n\n  install     envolve o statusline de cada conta com o tap do Habblaud (faz backup do settings.json)\n  uninstall   restaura o statusline original de cada conta\n  status      mostra se o tap está instalado e quando chegou o último uso de cada conta\n\nOpções:\n  --dry-run        mostra o que mudaria, sem gravar nada\n  --node <cmd>     comando do node usado no statusline (padrão: detectado no PATH)\n  -h, --help       mostra esta ajuda\n\nContas: as mesmas do servidor (~/.claude* com projects/ ou sessions/, CLAUDE_CONFIG_DIR ou\nHABBLAUD_CLAUDE_DIRS). Uso capturado em HABBLAUD_USAGE_DIR (padrão ~/.habblaud/usage).": "Cách dùng: npm run usage:<install|uninstall|status> [-- tùy chọn]\n\n  install     gắn trình đọc Habblaud vào statusline của từng tài khoản (sao lưu settings.json)\n  uninstall   khôi phục statusline gốc\n  status      xem trình đọc đã cài và lần cuối nhận mức dùng\n\n  --dry-run     xem thay đổi, không ghi tệp\n  --node <cmd>  lệnh node dùng cho statusline (mặc định từ PATH)\n  -h, --help    hiện trợ giúp\n\nTài khoản giống server (~/.claude* có projects/ hoặc sessions/, CLAUDE_CONFIG_DIR hoặc HABBLAUD_CLAUDE_DIRS).\nMức dùng ghi tại HABBLAUD_USAGE_DIR (mặc định ~/.habblaud/usage).",
  "statusLine em formato desconhecido; nada foi alterado": "statusLine có định dạng không xác định; không thay đổi",
