  "Uso: npm run codex:bridge [-- opções]\n\nEntrega as mensagens do escritório às sessões do Codex quando o Habblaud roda no Docker (deixe rodando no computador).\n\nOpções:\n  --port <n>   porta do Habblaud (padrão: HABBLAUD_PORT ou {0})\n  --once       faz uma rodada só e sai\n  -h, --help   mostra esta ajuda\n\nBinário do Codex: HABBLAUD_CODEX_BIN ou `codex` do PATH.": "Cách dùng: npm run codex:bridge [-- tùy chọn]\n\nChuyển tin nhắn văn phòng tới Codex khi Habblaud chạy trong Docker (để chạy liên tục trên máy).\n\n  --port <n>  cổng Habblaud (mặc định HABBLAUD_PORT hoặc {0})\n  --once      chạy một lượt rồi thoát\n  -h, --help  trợ giúp\n\nChương trình Codex: HABBLAUD_CODEX_BIN hoặc `codex` trong PATH.",
