  "Entregando as mensagens do Habblaud (http://127.0.0.1:{0}) às sessões do Codex com {1}, e começando os agentes novos pedidos no escritório. Ctrl+C para parar.": "Đang chuyển tin Habblaud (http://127.0.0.1:{0}) tới phiên Codex bằng {1} và mở agent mới được yêu cầu từ văn phòng. Ctrl+C để dừng.",
  "Sem o Codex (codex no PATH ou HABBLAUD_CODEX_BIN): só começo os agentes novos pedidos no Habblaud (http://127.0.0.1:{0}). Ctrl+C para parar.": "Không có Codex (codex trong PATH hoặc HABBLAUD_CODEX_BIN): chỉ mở agent mới được yêu cầu trong Habblaud (http://127.0.0.1:{0}). Ctrl+C để dừng.",
  "Agentes novos rodam em segundo plano com {0} --bg (pasta confiável; senão, no app do Claude).": "Agent mới chạy nền bằng {0} --bg (thư mục tin cậy; nếu không, mở trong ứng dụng Claude).",
  "Sem o claude no PATH (ou HABBLAUD_CLAUDE_BIN): agentes novos abrem no app do Claude e esperam o Enter.": "Không có claude trong PATH (hoặc HABBLAUD_CLAUDE_BIN): agent mới mở trong ứng dụng Claude và chờ Enter.",
  "Ditado desligado: falta {0}.": "Nhập giọng nói tắt: thiếu {0}.",
  "Ditado: Whisper local ({0}), idiomas {1} detectados sozinhos.": "Nhập giọng nói: Whisper local ({0}), tự nhận diện ngôn ngữ {1}.",
  "conectado ao Habblaud.": "đã kết nối Habblaud.",
