  "acesso remoto: não consegui conferir o certificado ({0}).": "truy cập từ xa: không thể kiểm tra chứng chỉ ({0}).",
  "Acesso remoto: publica {0} (porta {1} do container).": "Truy cập từ xa: mở cổng {0} (cổng container {1}).",
  "--timeout precisa de um número de segundos entre 5 e 86400 (24 h).": "--timeout cần số giây từ 5 tới 86400 (24 giờ).",
  "[remote-mdns] sem HABBLAUD_REMOTE_NAME válido no .env: rode npm run remote:setup.": "[remote-mdns] HABBLAUD_REMOTE_NAME không hợp lệ trong .env: chạy npm run remote:setup.",
  "[remote-mdns] sem rede: anúncio suspenso.": "[remote-mdns] không có mạng: tạm dừng thông báo.",
  "[remote-mdns] {0} sem suporte: use o IP ou um endereço no DNS do roteador.": "[remote-mdns] không hỗ trợ {0}: dùng IP hoặc tên trong DNS router.",
  "[remote-mdns] não deu para rodar {0}: {1}": "[remote-mdns] không thể chạy {0}: {1}",
  "[remote-mdns] anunciando {0}.local -> {1}": "[remote-mdns] đang thông báo {0}.local -> {1}",
  "Uso: npm run remote:setup [-- opções]\n\nLiga o acesso pelo celular (https://<nome>.local) com usuário, senha e HTTPS.\n\n  --user <nome>        usuário do login (padrão: o seu usuário do sistema)\n  --name <nome>        endereço <nome>.local (padrão: habblaud)\n  --domain <endereço>  endereço próprio, ex.: meuclaude.home (precisa de uma entrada no DNS do roteador)\n  --port <n>           porta no computador (padrão: 443 se estiver livre, senão 4748)\n  --allow <lista>      o que o celular pode fazer: permissions, messages, terminal, spawn, none (padrão: permissions)\n  --password-stdin     lê a senha da entrada padrão (automação), em vez de perguntar\n  --no-service         não instala o serviço do anúncio <nome>.local (rode npm run remote:mdns você mesmo)\n  --off                desliga o acesso pelo celular (tira as linhas do .env e o serviço; mantém a CA)": "Cách dùng: npm run remote:setup [-- tùy chọn]\n\nBật truy cập điện thoại (https://<name>.local) có tên đăng nhập, mật khẩu và HTTPS.\n\n  --user <name>       tên đăng nhập (mặc định tên người dùng hệ thống)\n  --name <name>       địa chỉ <name>.local (mặc định habblaud)\n  --domain <address>  tên riêng, ví dụ myclaude.home (cần DNS router)\n  --port <n>          cổng trên máy (mặc định 443 nếu rảnh, nếu không dùng 4748)\n  --allow <list>      quyền điện thoại: permissions, messages, terminal, spawn, none (mặc định permissions)\n  --password-stdin    đọc mật khẩu từ stdin thay vì hỏi\n  --no-service        không cài dịch vụ .local (tự chạy npm run remote:mdns)\n  --off               tắt truy cập điện thoại (gỡ cấu hình .env và dịch vụ; giữ CA)",
