  "Mandamos um código de 6 dígitos para {0}. Ele vale por 10 minutos.": "Đã gửi mã 6 chữ số tới {0}. Mã có hiệu lực 10 phút.",
  "Não chegou? Confira o spam ou peça outro. Se este e-mail já tinha conta, a mensagem avisa: aí é só entrar com a senha.": "Chưa nhận được? Kiểm tra thư rác hoặc yêu cầu mã khác. Nếu email đã có tài khoản, thư sẽ thông báo: chỉ cần đăng nhập bằng mật khẩu.",
  "Usar outro e-mail": "Dùng email khác",
  "Mandar código": "Gửi mã",
  "Mandando…": "Đang gửi…",
  "Digite o e-mail da conta. Se ele estiver cadastrado, chega um código para criar uma senha nova.": "Nhập email tài khoản. Nếu đã đăng ký, bạn sẽ nhận mã để tạo mật khẩu mới.",
  "Senha nova": "Mật khẩu mới",
  "Trocar a senha": "Đổi mật khẩu",
  "Trocando…": "Đang đổi…",
  "Trocar a senha desconecta todos os dispositivos da conta.": "Đổi mật khẩu sẽ đăng xuất mọi thiết bị của tài khoản.",
  "Se {0} tiver conta, chegou um código de 6 dígitos. Digite o código e a senha nova.": "Nếu {0} có tài khoản, mã 6 chữ số đang được gửi. Nhập mã và mật khẩu mới.",
  "Acesso liberado!": "Đã cấp quyền truy cập!",
  "Você está na lista de espera. Estamos liberando o acesso aos poucos e avisamos por e-mail quando chegar a sua vez.": "Bạn đang trong danh sách chờ. Quyền truy cập mở dần, chúng tôi sẽ báo qua email khi tới lượt.",
  "Seu prédio vai aparecer aqui": "Tòa nhà của bạn sẽ hiện tại đây",
  "país escondido": "đã ẩn quốc gia",
  "Crie o seu personagem para entrar no mundo.": "Tạo nhân vật để vào thế giới.",
  "Enquanto espera, já dá para criar o seu personagem.": "Trong lúc chờ, bạn có thể tạo nhân vật.",
