  "Muda detalhes do rosto e o sorteio de cabelo e roupa; tudo dá para trocar nas peças abaixo.": "Đổi chi tiết mặt và cách chọn tóc/quần áo ngẫu nhiên; bạn có thể sửa mọi thứ bên dưới.",
  "Já são 3 traços: desmarque um para trocar.": "Đã có 3 tính cách: bỏ một để đổi.",
