  "Habblaud World: prédio conectado.": "Habblaud World: tòa nhà đã kết nối.",
  "Habblaud World: o servidor recusou o pacote do prédio ({0}).": "Habblaud World: server từ chối gói tòa nhà ({0}).",
  "Habblaud World: esta versão do Habblaud não entra mais no mundo; atualize para o prédio voltar.": "Habblaud World: phiên bản Habblaud này không còn tham gia được; cập nhật để đưa tòa nhà trở lại.",
