  "Nenhuma remessa ainda": "Chưa gửi lần nào",
  "Aceso no mundo: um andar por sala aberta e cada personagem no status de agora. Os tokens, se você deixar, aparecem só em faixas, no medidor da fachada.": "Sáng trong World: mỗi phòng mở là một tầng, mỗi nhân vật có trạng thái hiện tại. Token, nếu cho phép, chỉ hiện theo khoảng trên đồng hồ mặt tiền.",
  "O prédio acende com a primeira remessa.": "Tòa nhà sáng sau lần gửi đầu tiên.",
  "Sem conexão com o mundo agora: o Habblaud tenta de novo sozinho. Com 2 minutos sem notícias, o prédio apaga.": "Hiện không có kết nối World: Habblaud tự thử lại. Sau 2 phút không có dữ liệu, tòa nhà tắt đèn.",
  "Pausado: seu prédio está apagado, mas você pode andar pela cidade. Nada do escritório sai deste computador.": "Đã tạm dừng: tòa nhà tối nhưng bạn vẫn đi trong thành phố. Không gửi dữ liệu văn phòng khỏi máy này.",
  "Crie o seu personagem: o prédio entra no mundo junto com ele.": "Tạo nhân vật: tòa nhà sẽ cùng tham gia World.",
  "Pausar interrompe o envio na hora e apaga o prédio no mundo.": "Tạm dừng sẽ ngừng gửi ngay và tắt đèn tòa nhà trong World.",
  "Retomar volta a enviar e acende o prédio.": "Tiếp tục sẽ gửi lại và bật đèn tòa nhà.",
  "Pausado por 30 dias, o prédio some do mapa e, 30 dias depois, é retirado; retomar antes disso traz de volta, no mesmo lote.": "Sau 30 ngày tạm dừng, tòa nhà biến mất khỏi bản đồ và bị xóa sau 30 ngày nữa; tiếp tục trước đó để trở lại cùng lô đất.",
  "O mundo recusou a última remessa.": "World từ chối lần gửi cuối.",
  "O pacote saiu fora do formato do protocolo. Atualize o Habblaud.": "Gói không đúng định dạng giao thức. Cập nhật Habblaud.",
  "O escritório passou dos limites do mundo (64 andares, 64 agentes por andar, 256 agentes ou 64 KB).": "Văn phòng vượt giới hạn World (64 tầng, 64 agent mỗi tầng, tổng 256 agent hoặc 64 KB).",
  "Um nome de personagem não está na lista de nomes do mundo.": "Tên nhân vật không có trong danh sách tên của World.",
  "Uma peça de aparência está fora das paletas do editor.": "Phần ngoại hình ngoài bảng màu của trình chỉnh sửa.",
  "Um código de andar ou de agente está fora do formato.": "Mã tầng hoặc agent sai định dạng.",
  "Remessas demais em pouco tempo (o limite é 12 por minuto). A próxima vai normalmente.": "Gửi quá nhiều trong thời gian ngắn (giới hạn 12 lần/phút). Lần tiếp theo sẽ gửi bình thường.",
  "Um motivo que esta versão do Habblaud não conhece.": "Lý do phiên bản Habblaud này chưa biết.",
