  "Isto é tudo o que saiu do seu computador. Nenhum caminho, nome de projeto, texto ou horário do escritório.": "Đây là toàn bộ dữ liệu rời máy. Không có đường dẫn, tên dự án, văn bản hay thời gian văn phòng.",
  "Pacote enviado (JSON)": "Gói đã gửi (JSON)",
  "O tema também vale para o seu prédio no Habblaud World.": "Chủ đề cũng áp dụng cho tòa nhà trong Habblaud World.",
