  "pausado": "đã tạm dừng",
  "Seu prédio está aceso no Habblaud World: {0} e {1}. Clique para abrir o Habblaud World.": "Tòa nhà đang sáng trong Habblaud World: {0} và {1}. Bấm để mở Habblaud World.",
  "Pausado: seu prédio está apagado, mas você pode andar pela cidade. Nada do escritório sai deste computador; clique para retomar.": "Đã tạm dừng: tòa nhà tối nhưng bạn vẫn dạo thành phố. Không gửi dữ liệu văn phòng khỏi máy; bấm để tiếp tục.",
  "Sem conexão com o Habblaud World agora; o Habblaud tenta de novo sozinho. Clique para ver o seu prédio.": "Hiện mất kết nối Habblaud World; Habblaud tự thử lại. Bấm để xem tòa nhà.",
