  "Esta conta está suspensa no Habblaud World: o prédio fica apagado e nada sai deste computador.": "Tài khoản đang bị đình chỉ trong Habblaud World: tòa nhà tối, không gửi dữ liệu khỏi máy.",
  "Esta versão do Habblaud não entra mais no mundo. Atualize para o prédio voltar a acender.": "Phiên bản Habblaud này không còn tham gia World được. Cập nhật để tòa nhà sáng lại.",
  "Fora do mundo": "Ngoài World",
  "O Habblaud World baniu esta conta: o prédio saiu do mundo e nada mais sai deste computador.": "Habblaud World cấm tài khoản này: tòa nhà đã rời World và không gửi thêm dữ liệu khỏi máy.",
  "O mundo contou {0}.": "World đã đếm {0}.",
  "O mundo não encontrou o seu personagem: crie de novo para o prédio voltar.": "World không tìm thấy nhân vật: tạo lại để đưa tòa nhà trở lại.",
  "O mundo recebeu os mesmos {0}.": "World nhận cùng {0}.",
  "O prédio volta a subir daqui, e o outro computador para de enviar.": "Tòa nhà gửi lại từ đây, máy khác ngừng gửi.",
  "O servidor do mundo não reconheceu este computador: entre de novo na conta.": "Server World không nhận ra máy này: đăng nhập lại tài khoản.",
  "parado": "đã dừng",
  "Pausar apaga o prédio e guarda o lote: retomar traz de volta, no mesmo lugar. Sair do mundo retira o prédio na hora e libera o lote; a conta e o personagem continuam, e voltar depois cria um prédio novo, em outro lote.": "Tạm dừng tắt đèn và giữ lô đất: tiếp tục để trở lại đúng chỗ. Rời World xóa tòa nhà ngay và giải phóng đất; giữ tài khoản, nhân vật, quay lại sau sẽ tạo tòa nhà mới trên lô khác.",
  "Sair do mundo": "Rời World",
  "Se a suspensão já acabou, o prédio volta a acender.": "Nếu hết đình chỉ, tòa nhà sáng lại.",
  "Seu prédio parou de subir ao Habblaud World. Clique para ver o motivo.": "Tòa nhà đã dừng gửi tới Habblaud World. Bấm để xem lý do.",
  "Trazer para este computador": "Chuyển về máy này",
  "Você saiu do mundo: o prédio foi retirado e o lote, liberado. Dá para andar pela cidade; nada do escritório sai deste computador.": "Bạn đã rời World: tòa nhà bị xóa, đất được giải phóng. Bạn vẫn dạo thành phố được; không gửi dữ liệu văn phòng khỏi máy.",
  "Voltar ao mundo": "Trở lại World",
  "Voltar cria um prédio novo, em outro lote; a conta e o personagem são os mesmos.": "Trở lại sẽ tạo tòa nhà mới trên lô khác; tài khoản và nhân vật giữ nguyên.",
  "A cidade já está aberta em outras abas do Habblaud. Feche uma delas para abrir aqui.": "Thành phố đang mở ở các tab Habblaud khác. Đóng một tab để mở tại đây.",
  "A cena Mundo perdeu a conexão com o Habblaud. Abra a cidade de novo.": "Cảnh World mất kết nối Habblaud. Mở lại thành phố.",
  "A conta saiu do mundo (por este ou por outro computador): nada mais sai até você voltar ao mundo.": "Tài khoản đã rời World (trên máy này hoặc máy khác): không gửi thêm tới khi bạn trở lại.",
