  "A conta do Habblaud World foi excluída. O prédio e o perfil saíram do mundo na hora; o resto é apagado do banco em 7 dias e dos backups em até 30.": "Tài khoản Habblaud World đã xóa. Tòa nhà và hồ sơ rời World ngay; dữ liệu còn lại xóa khỏi cơ sở dữ liệu trong 7 ngày, bản sao lưu trong 30 ngày.",
  "Habblaud World: conta excluída; a sessão e o world.json foram apagados deste computador.": "Habblaud World: tài khoản đã xóa; phiên và world.json đã được gỡ khỏi máy này.",
  "os dados da conta só saem pela própria página do Habblaud": "dữ liệu tài khoản chỉ tải xuống qua trang Habblaud",
  "a conta, o personagem, os likes dados e recebidos, os bloqueios, as denúncias feitas e os dispositivos são apagados do banco.": "tài khoản, nhân vật, lượt thích đã gửi/nhận, danh sách chặn, báo cáo của bạn và thiết bị được xóa khỏi cơ sở dữ liệu.",
  "Abre um e-mail para {0}: conte o que aconteceu, e uma pessoa revê o caso.": "Mở email tới {0}: mô tả sự việc, nhân viên sẽ xem xét.",
  "Abre um e-mail para {0}: se for engano, uma pessoa revê os números e tira o selo.": "Mở email tới {0}: nếu nhầm lẫn, nhân viên kiểm tra số liệu và gỡ nhãn.",
