  "Não verificado": "Chưa xác minh",
  "O aviso de inatividade fica disponível depois de criar o personagem.": "Cảnh báo không hoạt động khả dụng sau khi tạo nhân vật.",
  "O mundo marcou o seu prédio como \"não verificado\": os números pareceram fora do normal e estão em revisão. Ele continua no mundo, mas fora de placares e destaques.": "World gắn nhãn \"chưa xác minh\" cho tòa nhà: số liệu bất thường, đang xem xét. Tòa nhà vẫn ở World nhưng không vào bảng xếp hạng hay mục nổi bật.",
  "o prédio e o perfil somem do mundo, e este computador sai da conta.": "tòa nhà và hồ sơ biến mất khỏi World, máy này đăng xuất tài khoản.",
  "Os números deste prédio pareceram fora do normal e estão em revisão; enquanto isso, ele fica fora de placares e destaques.": "Số liệu tòa nhà bất thường, đang xem xét; trong lúc chờ không tham gia bảng xếp hạng hay mục nổi bật.",
  "Para confirmar, mandamos um código de 6 dígitos para o e-mail da conta ({0}).": "Để xác nhận, chúng tôi gửi mã 6 chữ số tới email tài khoản ({0}).",
