  "Recorrer por e-mail": "Khiếu nại qua email",
  "Se quiser guardar uma cópia, baixe os seus dados antes.": "Nếu muốn giữ bản sao, hãy tải dữ liệu trước.",
  "Sem notícias deste Habblaud por 7 dias, o prédio some do mapa e, 30 dias depois, é retirado. O e-mail chega 3 dias antes da retirada.": "Sau 7 ngày không có dữ liệu từ Habblaud này, tòa nhà biến mất khỏi bản đồ và bị xóa sau 30 ngày nữa. Email tới 3 ngày trước khi xóa.",
  "Seus dados": "Dữ liệu của bạn",
  "somem também dos backups.": "dữ liệu cũng biến mất khỏi bản sao lưu.",
  "Tem certeza? O prédio e o perfil saem do mundo assim que você digitar o código.": "Bạn chắc chứ? Tòa nhà và hồ sơ rời World ngay khi bạn nhập mã.",
  "Um arquivo JSON com o que o Habblaud World guarda da sua conta: e-mail, datas, personagem, visibilidade, dispositivos, prédio, likes dados, bloqueios e denúncias feitas. Dá para baixar uma vez por dia.": "Tệp JSON chứa dữ liệu Habblaud World lưu về tài khoản: email, ngày, nhân vật, hiển thị, thiết bị, tòa nhà, lượt thích đã gửi, chặn và báo cáo của bạn. Tải được một lần mỗi ngày.",
  "O pacote contradiz o anterior de um jeito que o Habblaud não produz: o mundo o descartou, e o prédio fica com o último aceito. As próximas remessas vão normalmente.": "Gói mâu thuẫn với gói trước theo cách Habblaud không tạo ra: World bỏ qua, tòa nhà giữ gói cuối được chấp nhận. Lần gửi tiếp theo vẫn bình thường.",
